import express from "express";

const app = express();

app.get("/slow-cpu", (_req, res) => {
  const start = Date.now();
  while (Date.now() - start < 3000) {} // блокирует event loop
  res.json({ blockedMs: 3000 });
});

app.get("/fast", (_req, res) => res.json({ ok: true }));

app.listen(3000);
